package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"net/http/httptest"
	"time"
)

func publish(ctx context.Context, topic string) error {
	select {
	case <-time.After(50 * time.Millisecond): // the broker needs a moment
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func handler(w http.ResponseWriter, r *http.Request) {
	go func() {
		if err := publish(r.Context(), "order.created"); err != nil {
			log.Println("publish failed:", err)
		}
	}()
	fmt.Fprintln(w, "ok")
}

func main() {
	srv := httptest.NewServer(http.HandlerFunc(handler))
	defer srv.Close()
	resp, err := http.Get(srv.URL)
	if err != nil {
		return
	}
	resp.Body.Close()
	time.Sleep(200 * time.Millisecond)
}
